const raw =
  $json.output?.[0]?.content?.[0]?.text ??
  $json.message?.content ??
  $json.text ??
  $json;

let d = raw;
if (typeof raw === 'string') {
  const clean = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  d = JSON.parse(clean);
}

const errors = [];
const isInt = (v) => Number.isInteger(v);
const allowedTax = new Set([0, 7, 19, null]);

if (!d || typeof d !== 'object') throw new Error('OpenAI-Ausgabe ist kein Objekt');
if (!Array.isArray(d.lines) || d.lines.length === 0) errors.push('Keine Rechnungspositionen erkannt');
if (!d.supplier_name) errors.push('Lieferant fehlt');
if (!d.invoice_number && d.document_type !== 'shift4_statement') errors.push('Rechnungsnummer fehlt');
if (!d.invoice_date) errors.push('Rechnungsdatum fehlt');
if (!isInt(d.gross_cents)) errors.push('Bruttobetrag fehlt oder ist nicht in Cent');
if (!isInt(d.net_cents)) errors.push('Nettobetrag fehlt oder ist nicht in Cent');
if (!isInt(d.tax_cents)) errors.push('USt-Betrag fehlt oder ist nicht in Cent');

let lineGross = 0;
let lineNet = 0;
let lineTax = 0;

for (let i = 0; i < (d.lines || []).length; i++) {
  const l = d.lines[i];
  if (!l.description) errors.push(`Position ${i + 1}: Beschreibung fehlt`);
  if (!isInt(l.net_cents)) errors.push(`Position ${i + 1}: netto_cents ungültig`);
  if (!isInt(l.tax_cents)) errors.push(`Position ${i + 1}: tax_cents ungültig`);
  if (!isInt(l.gross_cents)) errors.push(`Position ${i + 1}: gross_cents ungültig`);
  if (!allowedTax.has(l.tax_rate ?? null)) errors.push(`Position ${i + 1}: Steuersatz ungültig`);
  if ((l.confidence ?? 0) < 80) errors.push(`Position ${i + 1}: Kontierung/Extraktion unsicher (${l.confidence ?? 0}%)`);
  lineGross += Number(l.gross_cents || 0);
  lineNet += Number(l.net_cents || 0);
  lineTax += Number(l.tax_cents || 0);
}

if (isInt(d.gross_cents) && Math.abs(lineGross - d.gross_cents) > 2) {
  errors.push(`Positionssumme Brutto weicht ab: ${lineGross} ct statt ${d.gross_cents} ct`);
}
if (isInt(d.net_cents) && Math.abs(lineNet - d.net_cents) > 2) {
  errors.push(`Positionssumme Netto weicht ab: ${lineNet} ct statt ${d.net_cents} ct`);
}
if (isInt(d.tax_cents) && Math.abs(lineTax - d.tax_cents) > 2) {
  errors.push(`Positionssumme USt weicht ab: ${lineTax} ct statt ${d.tax_cents} ct`);
}
if (isInt(d.net_cents) && isInt(d.tax_cents) && isInt(d.gross_cents) &&
    Math.abs((d.net_cents + d.tax_cents) - d.gross_cents) > 2) {
  errors.push('Netto + USt entspricht nicht Brutto');
}

const attachment = $('PDF normalisieren').item;
const metadata = attachment.json.accounting_attachment;
if (!metadata?.source_reference || !attachment.binary?.eingangsrechnung_0) {
  throw new Error('Original-PDF oder Anhangsreferenz fehlt.');
}
const fileName = metadata.original_filename;
const sourceReference = metadata.source_reference;

const portalPayload = {
  source: 'n8n',
  source_reference: sourceReference,
  supplier_name: d.supplier_name ?? null,
  invoice_number: d.invoice_number ?? null,
  invoice_date: d.invoice_date ?? null,
  service_date_from: d.service_date_from ?? null,
  service_date_to: d.service_date_to ?? null,
  currency: d.currency || 'EUR',
  net_cents: d.net_cents ?? null,
  tax_cents: d.tax_cents ?? null,
  gross_cents: d.gross_cents ?? null,
  confidence: d.confidence ?? 0,
  original_filename: fileName,
  validation_errors: errors,
  raw_payload: {
    document_type: d.document_type || 'purchase_invoice',
    original_binary_key: metadata.original_binary_key,
    extracted_text: $('Kassenberichte ausschließen').item.json.text
  },
  lines: (d.lines || []).map((l, i) => ({
    position_no: l.position_no ?? (i + 1),
    article_number: l.article_number ?? null,
    description: l.description || `Position ${i + 1}`,
    quantity: l.quantity ?? null,
    unit: l.unit ?? null,
    net_cents: l.net_cents ?? null,
    tax_rate: l.tax_rate ?? null,
    tax_cents: l.tax_cents ?? null,
    gross_cents: l.gross_cents ?? null,
    account_number: l.account_number ?? null,
    confidence: l.confidence ?? 0,
    classification_source: l.classification_source || 'ai'
  }))
};

return {
  binary: { eingangsrechnung_0: attachment.binary.eingangsrechnung_0 },
  json: {
    ...d,
    validation_status: errors.length ? 'REVIEW' : 'VALID',
    validation_errors: errors,
    source_reference: sourceReference,
    original_filename: fileName,
    portal_payload: portalPayload
  }
};

// n8n Code node, runOnceForAllItems. Preserve item linking for each attachment.
const result = [];
const inputs = $input.all();
for (let index = 0; index < inputs.length; index++) {
    const mail = inputs[index];
    const data = mail.json ?? {};
    const sender = data.from ?? data.metadata?.from ?? data.headers?.from;
    const addresses = [];
    function collect(value) {
        if (Array.isArray(value)) return value.forEach(collect);
        if (value && typeof value === 'object') {
            if (value.address) collect(value.address);
            if (value.value) collect(value.value);
            if (value.text) collect(value.text);
        } else if (typeof value === 'string') {
            addresses.push(...(value.match(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+/gi) ?? []));
        }
    }
    collect(sender);
    if (addresses.some(address => address.toLowerCase() === 'noreply@myvectron.com')) continue;

    const binaries = mail.binary ?? {};
    const pdfKeys = Object.keys(binaries).filter(key => {
        const file = binaries[key];
        return file?.mimeType?.toLowerCase() === 'application/pdf' || /\.pdf$/i.test(file?.fileName ?? '');
    });
    // Other mail and image attachments do not interrupt invoice processing.
    if (!pdfKeys.length) continue;

    const messageId = data.metadata?.['message-id'] ?? data.metadata?.messageId ?? data.messageId ?? data.headers?.['message-id'];
    const uid = data.attributes?.uid;
    const validity = data.attributes?.uidValidity ?? data.attributes?.uidvalidity;
    const base = typeof messageId === 'string' && messageId.trim()
        ? messageId.trim()
        : uid != null && validity != null ? `imap:rechnung@hemingway-hilden.de:${validity}:${uid}` : null;
    if (!base) throw new Error('Stabile Message-ID oder IMAP UIDVALIDITY + UID fehlt.');

    for (let position = 0; position < pdfKeys.length; position++) {
        const key = pdfKeys[position];
        // Keep legacy identity for the first PDF; additional originals are independent.
        const reference = position === 0 ? base : `${base}:attachment:${encodeURIComponent(key)}`;
        if (reference.length > 255) throw new Error('Quellreferenz überschreitet 255 Zeichen.');
        result.push({
            json: {
                ...data,
                ...(data.accounting_mail_uid ? { accounting_mail: { uid: data.accounting_mail_uid, expected_pdf_count: pdfKeys.length } } : {}),
                accounting_attachment: {
                    source_reference: reference,
                    original_filename: binaries[key].fileName ?? `${key}.pdf`,
                    original_binary_key: key,
                },
            },
            binary: { eingangsrechnung_0: binaries[key] },
            pairedItem: { item: index },
        });
    }
}
return result;

// In the polling loop, skipped cash reports must still complete their attachment iteration.
return $input.all().map((item, index) => {
    const text = item.json?.text;
    if (typeof text !== 'string' || !text.trim()) throw new Error('PDF enthält keinen auslesbaren Text; Mail bleibt im Posteingang.');
    const normalized = text.replace(/\s+/g, ' ');
    const skip = /(?:Finanzbericht|Bediener\s*\(erweitert\))\s*<\s*[ZX]\d+\s*>/i.test(normalized)
        || (/\bVectron\b/i.test(normalized) && /\bZ[-\s]?(?:Bericht|Zähler|Zaehler)\b/i.test(normalized));
    return { ...item, json: { ...item.json, skip_accounting: skip }, pairedItem: { item: index } };
});

// Gato branch bypasses AI. Laravel parses the original PDF and owns all accounting.
const attachment = $('PDF normalisieren').item;
const metadata = attachment.json.accounting_attachment;
if ($json.supplier !== 'gato' || $json.profile !== 'gato_layout_v1' || !metadata?.source_reference || !attachment.binary?.eingangsrechnung_0) {
    throw new Error('Gato-Lieferant, Referenz oder Original fehlt.');
}
return {
    json: {
        portal_payload: {
            source: 'n8n',
            source_reference: metadata.source_reference,
            supplier_name: 'Getränke Gato GmbH',
            extraction_profile: 'gato_layout_v1',
            original_filename: metadata.original_filename,
            extracted_text: $('Kassenberichte ausschließen').item.json.text ?? null,
        },
    },
    binary: { eingangsrechnung_0: attachment.binary.eingangsrechnung_0 },
};

// Reattach the exact original before the read-only content inspection request.
const attachment = $('PDF normalisieren').item;
if (!attachment.binary?.eingangsrechnung_0) throw new Error('Original-PDF fehlt.');
return { json: $json, binary: { eingangsrechnung_0: attachment.binary.eingangsrechnung_0 } };

// Exclude direct Vectron messages before downloading; forwarding sender is not a supplier criterion.
return $input.all().flatMap((item, index) => {
    const source = item.json;
    const values = [];
    function collect(value) {
        if (Array.isArray(value)) return value.forEach(collect);
        if (value && typeof value === 'object') {
            collect(value.address); collect(value.value); collect(value.text);
        } else if (typeof value === 'string') values.push(value);
    }
    collect(source.envelope?.from ?? source.from ?? source.headers?.from);
    const addresses = values.flatMap(value => value.match(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+/gi) ?? []);
    if (addresses.some(address => address.toLowerCase() === 'noreply@myvectron.com')) return [];
    return [{ ...item, pairedItem: { item: index } }];
});

// The community IMAP node is the same one used by the working Z-report poller.
const source = $('IMAP - Ungelesene Mails suchen').item.json;
const uid = String(source.uid ?? '');
if (!/^[1-9]\d*$/.test(uid)) throw new Error('IMAP UID fehlt.');
return {
    json: {
        ...source,
        from: source.envelope?.from ?? source.from ?? source.headers?.from,
        messageId: typeof source.headers?.['message-id'] === 'string'
            ? source.headers['message-id'] : source.envelope?.messageId ?? source.messageId ?? null,
        accounting_mail_uid: uid,
    },
    binary: $binary,
};

// Execute once per PDF after a portal response, intentional skip or error output.
const original = $('PDF normalisieren').item;
const mail = original.json.accounting_mail;
if (!mail?.uid || !Number.isInteger(mail.expected_pdf_count)) throw new Error('Mail-/Anhangszuordnung fehlt.');
const kind = $json._polling_result;
const accepted = kind !== 'failed' && kind !== 'skipped'
    && Number.isInteger($json.document?.id) && $json.document.id > 0
    && typeof $json.document.file_path === 'string' && $json.document.file_path.length > 0;
return {
    json: {
        imap_uid: mail.uid,
        expected_pdf_count: mail.expected_pdf_count,
        attachment_key: original.json.accounting_attachment.original_binary_key,
        status: kind === 'skipped' ? 'skipped' : accepted ? 'accepted' : 'failed',
    },
};

// The done output is reached only after every queued PDF has produced an outcome.
const groups = new Map();
for (const item of $input.all()) {
    const row = item.json;
    if (!row.imap_uid || !row.attachment_key || !Number.isInteger(row.expected_pdf_count)) {
        throw new Error('Unvollständiges Verarbeitungsergebnis; keine Mail verschieben.');
    }
    const group = groups.get(row.imap_uid) ?? { expected: row.expected_pdf_count, outcomes: new Map(), invalid: false };
    if (group.expected !== row.expected_pdf_count || group.outcomes.has(row.attachment_key)) group.invalid = true;
    group.outcomes.set(row.attachment_key, row.status);
    groups.set(row.imap_uid, group);
}
const result = [];
for (const [uid, group] of groups) {
    const statuses = [...group.outcomes.values()];
    if (!group.invalid && statuses.length === group.expected
        && statuses.every(status => status === 'accepted' || status === 'skipped')
        && statuses.includes('accepted')) {
        result.push({ json: { imap_uid: uid } });
    }
}
return result;
